SELECT link_id, COUNT(*) AS 'count' FROM link_access_log WHERE link_id IN
#{linkId}
GROUP BY link_id

SELECT link_id, clickCount, province AS topProvince, latestClickTime FROM ( SELECT link_id, COUNT(*) OVER (PARTITION BY link_id) AS clickCount, ROW_NUMBER() OVER (PARTITION BY link_id ORDER BY create_time DESC) AS rn, province, create_time AS latestClickTime FROM link_access_log WHERE link_id IN
#{linkId}
) t WHERE rn = 1;

SELECT link_id, COUNT(*) AS 'count' FROM link_access_log WHERE link_id IN
#{linkId}
AND create_time >= #{dto.startDate} AND create_time < DATE_ADD(#{dto.endDate}, INTERVAL 1 DAY) GROUP BY link_id ORDER BY count DESC LIMIT #{dto.topN}

SELECT DATE(create_time) as 'time', COUNT(*) AS 'clickCount' FROM link_access_log WHERE link_id IN
#{linkId}
AND create_time >= #{dto.startDate} AND create_time < DATE_ADD(#{dto.endDate}, INTERVAL 1 DAY) GROUP BY DATE(create_time)
